      - run: git branch --track main origin/main
        if: github.event_name == 'pull_request' || github.event_name == 'merge_group'

      - uses: nrwl/nx-set-shas@v5
      - run: |
          echo "BASE: ${{ env.NX_BASE }}"
          echo "HEAD: ${{ env.NX_HEAD }}"

      # Starts the Nx Cloud workers (.nx/ci-config.yaml, .nx/workflows/workers.yml).
      # After the install on purpose: run through npx before node_modules exist, the
      # command cannot resolve the nx package and requests no workers (the run then
      # waits forever), and here NX_BASE/NX_HEAD are forwarded to the workers too.
      - run: npx nx-cloud start-workers

      - name: Format check
        run: npx nx format:check

      - name: Sync check
        run: npx nx sync:check

      # Outside Nx on purpose: renaming a file a target input names makes only
      # that file's project affected, never tools, so tools:test would miss it.
      - name: Target inputs name existing files
        run: node --test tools/ci/target-inputs.test.mjs

      # Outside Nx too: a new script makes only its own project affected, so
      # tools:test would miss one that no tsconfig owns (#3133).
      - name: Scripts belong to their tsconfig
        run: node --test tools/ci/script-tsconfig.test.mjs

      - name: run-checks in parallel on nx cloud workers
        run: |
          npx nx affected -t="lint,lint-templates,typecheck-specs,typecheck-tools,test,test-emulator,build,e2e-ci,perf,lighthouse" -c=ci

      - name: Auto Fix CI
        if: always()
